<section id="concept" class="active">

  <!-- 卡片1：什么是分数 -->
  <div class="card card-blue">
    <h2>🔍 一、先来认识分数</h2>
    <p>把一个整体<strong>平均分成</strong>若干份，其中的几份就可以用<strong>分数</strong>来表示！</p>
    <div style="text-align:center; margin:20px 0;">
      <svg width="320" height="120" viewBox="0 0 320 120">
        <!-- 一个圆平均分成4份，涂了3份 -->
        <circle cx="60" cy="60" r="50" fill="#fff" stroke="#333" stroke-width="2.5"/>
        <line x1="60" y1="10" x2="60" y2="110" stroke="#333" stroke-width="2"/>
        <line x1="10" y1="60" x2="110" y2="60" stroke="#333" stroke-width="2"/>
        <path d="M60,60 L60,10 A50,50 0 0,1 110,60 Z" fill="#4fc3f7"/>
        <path d="M60,60 L110,60 A50,50 0 0,1 60,110 Z" fill="#4fc3f7"/>
        <path d="M60,60 L60,110 A50,50 0 0,1 10,60 Z" fill="#4fc3f7"/>
        <text x="60" y="130" text-anchor="middle" font-size="18" font-weight="bold" fill="#e53935">3/4</text>

        <!-- 等号 -->
        <text x="160" y="65" text-anchor="middle" font-size="30" font-weight="bold" fill="#ff9800">=</text>

        <!-- 说明 -->
        <text x="220" y="35" font-size="15" fill="#333">把一个圆</text>
        <text
